import subprocess
import sys


def test_public_access_boundary():
 subprocess.run([sys.executable,"-c","import os\nos.environ['REPORT_PUBLIC']='1'\nos.environ['REPORT_SESSION_SECRET']='test-session-secret-'*3\nos.environ['REPORT_ADMIN_PASSWORD']='test-admin-password-'*2\nos.environ['REPORT_AGENT_DATA']=__import__('tempfile').mkdtemp()\nfrom fastapi.testclient import TestClient\nfrom report_agent.api import app\nfrom report_agent import access\nwith TestClient(app, base_url='https://testserver') as a, TestClient(app, base_url='https://testserver') as b:\n    assert a.get('/api/session').json()['admin'] is False\n    assert b.get('/api/session').status_code == 200\n    owner=access.identity(a.cookies.get(access.COOKIE))\n    access.claim('a'*32,owner)\n    for suffix in ['', '/files','/events','/stream','/input/sales','/download/docx']:\n        assert b.get('/api/runs/'+'a'*32+suffix).status_code==404\n    for method,path in [('get','/api/config'),('put','/api/config'),('put','/api/connection'),('put','/api/limits'),('post','/api/connection/test')]:\n        assert getattr(a,method)(path).status_code==403\n    assert a.post('/api/runs',headers={'origin':'https://evil.test'}).status_code==403\n    assert a.get('/admin',auth=('admin','wrong')).status_code==401\n    assert a.get('/admin',auth=('admin',os.environ['REPORT_ADMIN_PASSWORD'])).status_code==200\n    import base64\n    assert b.get('/admin',headers={'Authorization':'Basic '+base64.b64encode('admin:错误密码'.encode()).decode()}).status_code==401\n    assert a.get('/api/session').json()['admin'] is True\n    assert a.get('/api/config').status_code==200\n    assert a.post('/api/runs/'+'a'*32+'/review', json={}).status_code == 422\n    assert not access.identity('admin.1.fake')\n    assert access.consume([('test-limit',1)])\n    assert not access.consume([('test-limit',1)])\nprint('Access isolation, admin boundaries, origin checks and quota tests passed')\n"],check=True,timeout=60)
